import{_ as e,o as n,c as i,a1 as r}from"./chunks/framework.DxqwKiYY.js";const k=JSON.parse('{"title":"Modul 6 - Pengembangan Akhir","description":"","frontmatter":{},"headers":[],"relativePath":"Training WebGIS BIG/Modul 6 - Pengembangan Akhir.md","filePath":"Training WebGIS BIG/Modul 6 - Pengembangan Akhir.md"}'),t={name:"Training WebGIS BIG/Modul 6 - Pengembangan Akhir.md"};function s(o,a,l,m,u,g){return n(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="modul-6-pengembangan-akhir" tabindex="-1">Modul 6 - Pengembangan Akhir <a class="header-anchor" href="#modul-6-pengembangan-akhir" aria-label="Permalink to &quot;Modul 6 - Pengembangan Akhir&quot;">​</a></h1><h2 id="tujuan-modul" tabindex="-1"><strong>Tujuan Modul</strong> <a class="header-anchor" href="#tujuan-modul" aria-label="Permalink to &quot;**Tujuan Modul**&quot;">​</a></h2><p>Modul ini bertujuan memberikan pemahaman dan keterampilan kepada peserta dalam mengintegrasikan backend ORM, manajemen otentikasi pengoperasian spatial server, serta publikasi data spasial berbasis web. Peserta akan mempelajari mekanisme akses data spasial dari PostgreSQL ke GeoServer, penginstalan GeoServer pada Virtual Machine, serta implementasi otentikasi aman menggunakan Prisma, NextAuth, dan access token.</p><p>Setelah menyelesaikan modul ini, peserta diharapkan mampu:</p><ol><li>Mengonfigurasi Prisma ORM dan membangun endpoint API untuk sistem autentikasi login.</li><li>Melakukan instalasi dan konfigurasi GeoServer pada lingkungan Virtual Machine (VM).</li><li>Menghubungkan basis data PostgreSQL ke GeoServer sebagai Data Store serta mempublikasikan layer spasial (Publish Layer).</li><li>Mengimplementasikan sistem otentikasi dan otorisasi menggunakan NextAuth dan access token untuk mengamankan hak akses aplikasi.</li></ol><h2 id="materi" tabindex="-1">Materi <a class="header-anchor" href="#materi" aria-label="Permalink to &quot;Materi&quot;">​</a></h2><p><a href="./Modul 6 - Pengembangan Akhir/Konfigurasi Prisma dan Membuat API Login.html">Konfigurasi Prisma dan Membuat API Login</a></p><p><a href="./Modul 6 - Pengembangan Akhir/Koneksi PostgreSQL ke Geoserver sebagai Data Store.html">Koneksi PostgreSQL ke Geoserver sebagai Data Store dan Publish Layer</a></p><p><a href="./Modul 6 - Pengembangan Akhir/Instalasi Geoserver di VM.html">Instalasi Geoserver di VM</a></p><p><a href="./Modul 6 - Pengembangan Akhir/Konfigurasi Access Token dan Next Auth.html">Konfigurasi Access Token dan Next Auth </a></p>',10)])])}const h=e(t,[["render",s]]);export{k as __pageData,h as default};
